readonly ExplorerDisk disk;List<ExportItem> cachedItems;System.Threading.Tasks.Task<List<ExportItem>> preparation;long prepared;readonly XboxEntry[] selected;readonly int uiThread=System.Threading.Thread.CurrentThread.ManagedThreadId;List<ExportItem> items{get{if(cachedItems==null){if(preparation==null)preparation=System.Threading.Tasks.Task.Run(()=>disk.ExportItems(selected,(s,a,b)=>System.Threading.Interlocked.Exchange(ref prepared,a)));var task=preparation;DateTime last=DateTime.MinValue;while(!task.IsCompleted){if(System.Threading.Thread.CurrentThread.ManagedThreadId==uiThread){Application.DoEvents();if((DateTime.UtcNow-last).TotalMilliseconds>=100){last=DateTime.UtcNow;progress("Preparing Windows copy",System.Threading.Interlocked.Read(ref prepared),0);}}System.Threading.Thread.Sleep(10);}cachedItems=task.GetAwaiter().GetResult();total=cachedItems.Where(i=>!i.Entry.Directory).Sum(i=>(long)i.Entry.Size);}return cachedItems;}}readonly Action<string,long,long> progress;readonly short descriptors,contents,effect;long done,total;
