public ShellExportData(ExplorerDisk source,IEnumerable<XboxEntry> entries,Action<string,long,long> report){disk=source;progress=report;selected=entries.ToArray();descriptors=unchecked((short)DataFormats.GetFormat("FileGroupDescriptorW").Id);contents=unchecked((short)DataFormats.GetFormat("FileContents").Id);effect=unchecked((short)DataFormats.GetFormat("Preferred DropEffect").Id);}
FORMATETC Format(short id,TYMED medium,int index){return new FORMATETC{cfFormat=id,dwAspect=DVASPECT.DVASPECT_CONTENT,lindex=index,tymed=medium};}
byte[] DescriptorBytes(){var b=new byte[checked(4+items.Count*592)];Buffer.BlockCopy(BitConverter.GetBytes(items.Count),0,b,0,4);for(int i=0;i<items.Count;i++){int at=4+i*592;var e=items[i];Buffer.BlockCopy(BitConverter.GetBytes(4u|64u|0x80000000u),0,b,at,4);Buffer.BlockCopy(BitConverter.GetBytes(e.Entry.Directory?16u:128u),0,b,at+36,4);Buffer.BlockCopy(BitConverter.GetBytes(e.Entry.Directory?0u:e.Entry.Size),0,b,at+68,4);var name=System.Text.Encoding.Unicode.GetBytes(e.Name);Buffer.BlockCopy(name,0,b,at+72,name.Length);}return b;}
