public int QueryGetData(ref FORMATETC f){if(f.dwAspect!=DVASPECT.DVASPECT_CONTENT)return DV_E_FORMATETC;if((f.cfFormat==descriptors||f.cfFormat==effect)&&(f.tymed&TYMED.TYMED_HGLOBAL)!=0&&f.lindex==-1)return 0;if(f.cfFormat==contents&&(f.tymed&TYMED.TYMED_ISTREAM)!=0&&f.lindex>=0&&f.lindex<items.Count&&!items[f.lindex].Entry.Directory)return 0;return DV_E_FORMATETC;}
public IEnumFORMATETC EnumFormatEtc(DATADIR direction){if(direction!=DATADIR.DATADIR_GET)throw new COMException("Unsupported direction",E_NOTIMPL);var formats=new List<FORMATETC>{Format(descriptors,TYMED.TYMED_HGLOBAL,-1),Format(effect,TYMED.TYMED_HGLOBAL,-1)};for(int i=0;i<items.Count;i++)if(!items[i].Entry.Directory)formats.Add(Format(contents,TYMED.TYMED_ISTREAM,i));return new Formats(formats.ToArray());}
