[ComVisible(true),ClassInterface(ClassInterfaceType.None)]sealed class Formats:IEnumFORMATETC{readonly FORMATETC[] formats;int at;public Formats(FORMATETC[] values){formats=values;}public int Next(int count,FORMATETC[] values,int[] fetched){int n=0;while(n<count&&at<formats.Length){values[n++]=formats[at++];}if(fetched!=null&&fetched.Length>0)fetched[0]=n;return n==count?0:1;}public int Skip(int count){int old=at;at=Math.Min(formats.Length,at+count);return at-old==count?0:1;}public int Reset(){at=0;return 0;}public void Clone(out IEnumFORMATETC copy){copy=new Formats(formats){at=at};}}
