[ComVisible(true),ClassInterface(ClassInterfaceType.None)]internal sealed class ShellExportStream:IStream {
readonly ExplorerDisk disk;readonly ExportItem item;readonly Action<int> progress;long position;
public ShellExportStream(ExplorerDisk source,ExportItem file,Action<int> report){disk=source;item=file;progress=report;}
public void Read(byte[] bytes,int count,IntPtr read){int n=disk.ReadExport(item,position,bytes,count);position+=n;if(read!=IntPtr.Zero)Marshal.WriteInt32(read,n);if(n>0)progress(n);}
public void Seek(long offset,int origin,IntPtr result){long next=checked((origin==0?0:origin==1?position:origin==2?item.Entry.Size:throwOrigin())+offset);if(next<0)throw new IOException("Negative stream position");position=next;if(result!=IntPtr.Zero)Marshal.WriteInt64(result,position);}static long throwOrigin(){throw new ArgumentException("Invalid seek origin");}
public void Stat(out System.Runtime.InteropServices.ComTypes.STATSTG stat,int flags){stat=new System.Runtime.InteropServices.ComTypes.STATSTG{type=2,cbSize=item.Entry.Size,grfMode=0};if((flags&1)==0)stat.pwcsName=item.Name;}
public void CopyTo(IStream target,long count,IntPtr read,IntPtr written){long copied=0;var buffer=new byte[65536];var ptr=Marshal.AllocHGlobal(4);try{while(copied<count){int n=disk.ReadExport(item,position,buffer,(int)Math.Min(buffer.Length,count-copied));if(n==0)break;Marshal.WriteInt32(ptr,0);target.Write(buffer,n,ptr);if(Marshal.ReadInt32(ptr)!=n)throw new IOException("Short destination write");position+=n;copied+=n;progress(n);}if(read!=IntPtr.Zero)Marshal.WriteInt64(read,copied);if(written!=IntPtr.Zero)Marshal.WriteInt64(written,copied);}finally{Marshal.FreeHGlobal(ptr);}}
public void Clone(out IStream clone){var c=new ShellExportStream(disk,item,progress);c.position=position;clone=c;}public void Commit(int flags){}public void Revert(){throw new NotSupportedException();}public void LockRegion(long a,long b,int c){throw new NotSupportedException();}public void UnlockRegion(long a,long b,int c){throw new NotSupportedException();}public void SetSize(long size){throw new NotSupportedException();}public void Write(byte[] b,int count,IntPtr done){throw new UnauthorizedAccessException("Read-only FATX stream");}
}
